#include <iostream>
#include <cstdio>
#include <cstring>
#include <queue>
#include <vector>
#include <algorithm>
using namespace std;

using ll = long long;
const int MAXN = 100010;
const int MAXM = 2000020;
const ll INF = 1000000000LL;

struct Edge {
    int next, to, cap;
    ll cost;
} e[MAXM];

int hd[MAXN], ecnt = 1, node_cnt;
vector<int> g[MAXN];

void link(int u, int v, int cap, ll cost) {
    e[++ecnt] = {hd[u], v, cap, cost};
    hd[u] = ecnt;
    e[++ecnt] = {hd[v], u, 0, -cost};
    hd[v] = ecnt;
}

namespace MCF {
    int cur[MAXN];
    bool vis[MAXN];
    ll dist[MAXN], pot[MAXN];

    struct State {
        int id;
        ll key;
        State(int i = 0, ll k = 0) : id(i), key(k) {}
        bool operator<(const State& o) const { return key > o.key; }
    };

    priority_queue<State> heap;

    bool spfa(int src, int dst) {
        fill(dist, dist + node_cnt + 1, INF);
        fill(cur, cur + node_cnt + 1, hd[src]);
        dist[dst] = 0;
        heap.push(State(dst, 0));

        while (!heap.empty()) {
            int u = heap.top().id;
            heap.pop();
            if (vis[u]) continue;
            vis[u] = true;

            for (int i = hd[u]; i; i = e[i].next) {
                int v = e[i].to;
                ll w = pot[u] + e[i ^ 1].cost - pot[v];
                if (e[i ^ 1].cap && dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    heap.push(State(v, dist[v]));
                }
            }
        }

        for (int i = 1; i <= node_cnt; ++i)
            pot[i] = min(pot[i] + dist[i], INF);

        if (!vis[src]) return false;
        fill(vis + 1, vis + node_cnt + 1, false);
        return true;
    }

    int dfs(int u, int dst, int flow) {
        if (u == dst || !flow) return flow;
        int pushed = 0;
        vis[u] = true;

        for (int& i = cur[u]; i; i = e[i].next) {
            if (e[i].cap) {
                int v = e[i].to;
                int f;
                if (!vis[v] && pot[v] + e[i].cost == pot[u] &&
                    (f = dfs(v, dst, min(flow, e[i].cap)))) {
                    e[i].cap -= f;
                    e[i ^ 1].cap += f;
                    pushed += f;
                    flow -= f;
                    if (!flow) break;
                }
            }
        }

        vis[u] = false;
        return pushed;
    }

    int total_flow;
    ll total_cost;

    void run(int src, int dst) {
        while (spfa(src, dst)) {
            int f = dfs(src, dst, INF);
            total_flow += f;
            total_cost += (ll)f * pot[src];
        }
    }
}

int src = 1, dst = 2, n, m, k, c, d;

inline int idx(int t, int x) { return t * n + x + 2; }

void layer(int t) {
    node_cnt += n;

    for (int u = 1; u <= n; ++u)
        for (int v : g[u])
            for (int p = 1; p <= k; ++p)
                link(idx(t, u), idx(t + 1, v), 1, d * (2 * p - 1));

    for (int u = 1; u <= n; ++u)
        link(idx(t, u), idx(t + 1, u), INF, 0);

    link(idx(t + 1, 1), dst, INF, c * (t + 1));
}

int main() {
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    node_cnt = n + 2;

    for (int i = 1; i <= k; ++i) {
        int a;
        scanf("%d", &a);
        link(src, idx(0, a), 1, 0);
    }

    for (int i = 1; i <= m; ++i) {
        int u, v;
        scanf("%d%d", &u, &v);
        g[u].push_back(v);
        g[v].push_back(u);
    }

    link(idx(0, 1), dst, INF, 0);

    for (int i = 0; i <= n + k; ++i)
        layer(i);

    MCF::run(src, dst);
    printf("%lld\n", MCF::total_cost);
    return 0;
}
